handleEvent(event) {
  switch (event.type) {
    case "click":
      this.#toggleSelectAllInputs(
        event.target.id === "selectAllAddressBooks"
          ? "addressBooks"
          : "calendars"
      );
      break;
    case "change":
      this.counterObserver[
        event.target.classList.contains("address-book-input")
          ? "addressBooks"
          : "calendars"
      ] += event.target.checked ? 1 : -1;
      break;
    default:
      break;
  }
}
